    always_comb begin : main_fsm
        // defaults: hold
        state_d          = state_q;
        flush_addr_d     = flush_addr_q;
        mshr_valid_d     = mshr_valid_q;
        mshr_addr_d      = mshr_addr_q;
        mshr_port_d      = mshr_port_q;
        amo_pending_d    = amo_pending_q;
        amo_clean_d      = amo_clean_q;
        amo_op_d         = amo_op_q;
        amo_size_d       = amo_size_q;
        amo_addr_d       = amo_addr_q;
        amo_data_d       = amo_data_q;
        victim_way_d     = victim_way_q;
        victim_addr_d    = victim_addr_q;
        victim_line_d    = victim_line_q;
        line_d           = line_q;
        r_beat_d         = r_beat_q;
        refill_ar_done_d = refill_ar_done_q;
        ev_aw_done_d     = ev_aw_done_q;
        ev_w_cnt_d       = ev_w_cnt_q;

        // ---- atomic bookkeeping, independent of the state (F6-F9) ----
        if (amo_take) begin
            amo_pending_d = 1'b1;
            amo_clean_d   = 1'b0;
            amo_op_d      = amo_req_i.amo_op;
            amo_size_d    = amo_req_i.size;
            amo_addr_d   = amo_req_i.operand_a;
            amo_data_d   = amo_req_i.operand_b;
        end
        if (|miss_gnt_o) begin
            amo_pending_d = 1'b0;          // F9: an incoming miss defers the atomic
        end
        if (amo_issue) begin
            amo_pending_d = 1'b0;          // handed to the bypass unit
        end
        if (walk_last) begin
            amo_clean_d = 1'b1;            // the completed walk flushed for it (F6)
        end

        // ---- miss grant: load the MSHR (F1) ----
        if (|miss_gnt_o) begin
            mshr_valid_d = 1'b1;
            mshr_addr_d  = reqs[miss_sel].addr;
            mshr_port_d  = miss_sel;
            r_beat_d     = 1'b0;
            refill_ar_done_d = 1'b0;
        end

        case (state_q)
            IDLE: begin
                if (flush_i && !busy_i) begin
                    state_d = FLUSH_R;                       // F5 (and F8's corner)
                end else if (|miss_gnt_o) begin
                    state_d = MISS_LOOKUP;                   // F1
                end else if (amo_take) begin
                    state_d = FLUSH_R;                      // F6: flush before the atomic
                end else if (amo_pending_q && !amo_clean_q && !busy_i) begin
                    state_d = FLUSH_R;                      // walk for a latched atomic
                end
            end
            FLUSH_R: begin
                state_d = FLUSH_W;
            end
            FLUSH_W: begin
                if (flush_addr_q == FLUSH_LAST) begin
                    flush_addr_d = '0;
                    state_d      = IDLE;
                end else begin
                    flush_addr_d = flush_addr_q + FLUSH_STEP;
                    state_d      = FLUSH_R;
                end
            end
            MISS_LOOKUP: begin
                state_d = MISS_DECIDE;
            end
            MISS_DECIDE: begin
                victim_way_d = victim_way_sel;
                if (victim_dirty_sel) begin
                    victim_addr_d = {data_i[victim_way_sel].tag, mshr_addr_q[11:4], 4'b0};
                    victim_line_d = data_i[victim_way_sel];
                    ev_aw_done_d  = 1'b0;
                    ev_w_cnt_d    = 2'd0;
                    state_d       = MISS_EVICT;
                end else begin
                    if (refill_ar_fire) begin
                        state_d = MISS_FETCH;
                    end
                end
            end
            MISS_EVICT: begin
                if (ev_done) begin
                    state_d = MISS_EVICT_B;
                end
            end
            MISS_EVICT_B: begin
                if (axi_data_rsp_i.b_valid) begin
                    state_d = MISS_FETCH;
                end
            end
            MISS_FETCH: begin
                if (axi_data_rsp_i.r_valid) begin
                    if (!r_beat_q) begin
                        line_d[63:0] = axi_data_rsp_i.r.data;
                        r_beat_d     = 1'b1;
                    end else begin
                        // last beat: the array write happens this cycle (Block H)
                        state_d      = IDLE;
                        mshr_valid_d = 1'b0;   // the refill retires (F3)
                    end
                end
            end
            default: state_d = state_q;
        endcase

        // ---- handshake progress (after the case: a fire in the first
        //      eviction cycle overrides the start-clear above) ----
        if (ev_aw_fire) begin
            ev_aw_done_d = 1'b1;
        end
        if (ev_w_fire) begin
            ev_w_cnt_d = ev_w_cnt_eff + 2'd1;
        end
        if (refill_ar_fire) begin
            refill_ar_done_d = 1'b1;
        end
    end
